static void init_led_device(void) {
    // LED1 - /dev/gpio0
    g_led_fd = open("/dev/gpio0", O_RDWR);
    if (g_led_fd >= 0) {
        ioctl(g_led_fd, GPIOC_SETPINTYPE, GPIO_OUTPUT_PIN);
        ioctl(g_led_fd, GPIOC_WRITE, 1);  // LED 默认熄灭（高电平熄灭）
        printf("[LED] LED initialized\n");
    } else {
        printf("[LED] open /dev/gpio0 failed\n");
    }
}

static void led_off_timer_cb(lv_timer_t *timer) {
    if (g_led_fd >= 0) {
        ioctl(g_led_fd, GPIOC_WRITE, 1);  // 熄灭
    }
    lv_timer_delete(timer);

