static void led_blink_once(void) {
    if (g_led_fd < 0) {
        printf("[LED] LED not initialized\n");
        return;
    }

    ioctl(g_led_fd, GPIOC_WRITE, 0);  // 点亮（低电平点亮）
    printf("[LED] LED ON\n");

