    lv_timer_create(led_off_timer_cb, 120, NULL);
}


/* ===========================================================
 * 新增功能：K1 按键控制 (基于 /dev/gpio1)
 * =========================================================== */
static void init_key_device(void) {
    g_key_fd = open("/dev/gpio1", O_RDWR);
    if (g_key_fd >= 0) {
        /* 配置为下拉输入模式 */
        ioctl(g_key_fd, GPIOC_SETPINTYPE, GPIO_INPUT_PIN_PULLDOWN);
        printf("[KEY] K1 initialized\n");
    } else {
        printf("[KEY] open /dev/gpio1 failed\n");
    }
}

static void key_poll_timer_cb(lv_timer_t *timer) {
    static bool last = false;
    bool now = false;

    if (g_key_fd < 0) {
        return;
    }

    if (ioctl(g_key_fd, GPIOC_READ, (unsigned long)((uintptr_t)&now)) < 0) {
        return;
    }

    /* 检测上升沿：当 K1 被按下时，触发 start_game */
    if (now && !last) {
        printf("[KEY] K1 pressed! Starting game...\n");
        start_game(NULL);
    }

    last = now;
}

