#define APP_ROLE_COUNT 6

static inline const char *app_role_at(int index)
{
    static const char *const roles[APP_ROLE_COUNT] = {
        "AI 应用开发",
        "AI Agent 开发",
        "大模型算法工程师",
        "AI/ML Engineer",
        "Data Scientist",
        "Data Analyst",
    };

    if (index < 0 || index >= APP_ROLE_COUNT) {
        return NULL;
