    return roles[index];
}

/* 岗位名 → 下标；不在表里返回 -1（例如 ROLE 环境变量给的是自定义值）。 */
static inline int app_role_index(const char *role)
{
    int i;

    if (role == NULL) {
        return -1;
    }
    for (i = 0; i < APP_ROLE_COUNT; i++) {
        if (strcmp(role, app_role_at(i)) == 0) {
            return i;
        }
    }
    return -1;
}

