    if (wav == NULL || wav_len == NULL) {
        return CLOUD_ERR_NOMEM;
    }
    *wav = NULL;
    *wav_len = 0;

    if (!g_initialized) {
        cloud_init();
    }
    if (text == NULL || text[0] == '\0') {
        return CLOUD_ERR_HTTP;
    }

    snprintf(url, sizeof(url), "%s/api/test/tts", app_cloud_base_url());

